import React from 'react';
import Image from 'next/image';
import { CheckCircle2, AlertCircle, ArrowRight, Check, ChevronDown } from 'lucide-react';

interface CheckoutFormProps {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    state: string;
    zip: string;
    country: string;
    plans: any[];
    selectedPlan: string;
    error: string;
    isLoading: boolean;
    termsAccepted: boolean;
    onStateChange: (key: string, value: string) => void;
    onPlanChange: (planId: string) => void;
    onTermsChange: (checked: boolean) => void;
    onSubmit: (e: React.FormEvent) => void;
}

const CheckoutForm: React.FC<CheckoutFormProps> = ({
    firstName, lastName, email, phone, address, city, zip, country,
    plans, selectedPlan, error, isLoading, termsAccepted,
    onStateChange, onPlanChange, onTermsChange, onSubmit
}) => {

    return (
        <form onSubmit={onSubmit} className="max-w-xl mx-auto space-y-8">
            {/* 1. Plan Selection */}
            <div>
                <h2 className="text-xl font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <span className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">1</span>
                    Select Challenge
                </h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {plans.map(plan => (
                        <div
                            key={plan.id}
                            onClick={() => onPlanChange(plan.id)}
                            className={`cursor-pointer p-4 border rounded-xl transition-all relative ${selectedPlan === plan.id
                                    ? 'border-indigo-600 bg-indigo-50 shadow-md ring-1 ring-indigo-600'
                                    : 'border-slate-200 hover:border-indigo-300 hover:bg-slate-50'
                                }`}
                        >
                            <h4 className={`font-bold text-sm ${selectedPlan === plan.id ? 'text-indigo-900' : 'text-slate-700'}`}>
                                {plan.name}
                            </h4>
                            <p className={`text-sm mt-1 font-bold ${selectedPlan === plan.id ? 'text-indigo-600' : 'text-slate-500'}`}>
                                ₹{plan.price.toLocaleString()}
                            </p>
                            {selectedPlan === plan.id && (
                                <div className="absolute top-3 right-3 text-indigo-600">
                                    <CheckCircle2 size={18} />
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* 2. Billing Details */}
            <div>
                <h2 className="text-xl font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <span className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">2</span>
                    Billing Details
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">First Name</label>
                        <input
                            type="text"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="John"
                            value={firstName}
                            onChange={e => onStateChange('firstName', e.target.value)}
                        />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Last Name</label>
                        <input
                            type="text"
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="Doe"
                            value={lastName}
                            onChange={e => onStateChange('lastName', e.target.value)}
                        />
                    </div>
                    <div className="md:col-span-2 space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Email</label>
                        <input
                            type="email"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="john@example.com"
                            value={email}
                            onChange={e => onStateChange('email', e.target.value)}
                        />
                    </div>
                    <div className="md:col-span-2 space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Phone</label>
                        <input
                            type="tel"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="+91"
                            value={phone}
                            onChange={e => onStateChange('phone', e.target.value)}
                        />
                    </div>
                    <div className="md:col-span-2 space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Address</label>
                        <input
                            type="text"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="Street Address"
                            value={address}
                            onChange={e => onStateChange('address', e.target.value)}
                        />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">City</label>
                        <input
                            type="text"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="City"
                            value={city}
                            onChange={e => onStateChange('city', e.target.value)}
                        />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Zip Code</label>
                        <input
                            type="text"
                            required
                            className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900"
                            placeholder="Zip"
                            value={zip}
                            onChange={e => onStateChange('zip', e.target.value)}
                        />
                    </div>
                    <div className="md:col-span-2 space-y-1">
                        <label className="text-xs font-semibold text-slate-700 uppercase">Country</label>
                        <div className="relative">
                            <select
                                className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none text-slate-900 appearance-none sh"
                                value={country}
                                onChange={e => onStateChange('country', e.target.value)}
                            >
                                <option value="India">India</option>
                                <option value="United States">United States</option>
                                <option value="United Kingdom">United Kingdom</option>
                                <option value="Canada">Canada</option>
                            </select>
                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Error Message */}
            {error && (
                <div className="p-4 bg-rose-50 border border-rose-100 rounded-lg flex items-start gap-3 text-rose-600 animate-shake">
                    <AlertCircle size={20} className="mt-0.5" />
                    <span className="text-sm font-medium">{error}</span>
                </div>
            )}

            {/* 3. Confirmation & Action */}
            <div className="pt-6 border-t border-slate-100 space-y-6">
                <label className="flex items-start gap-3 cursor-pointer group">
                    <div className={`mt-0.5 min-w-[20px] h-5 rounded border border-slate-300 flex items-center justify-center transition-all ${termsAccepted ? 'bg-indigo-600 border-indigo-600' : 'bg-white group-hover:border-indigo-400'}`}>
                        {termsAccepted && <Check size={14} className="text-white" />}
                    </div>
                    <input
                        type="checkbox"
                        className="hidden"
                        checked={termsAccepted}
                        onChange={(e) => onTermsChange(e.target.checked)}
                    />
                    <span className="text-xs text-slate-500 select-none leading-tight">
                        I agree to the <a href="#" className="text-indigo-600 hover:underline">Terms of Service</a>.
                    </span>
                </label>

                <button
                    type="submit"
                    disabled={isLoading}
                    className="w-full py-3 bg-[#635BFF] text-white rounded-lg font-bold text-base hover:bg-[#5851E3] active:opacity-90 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                    {isLoading ? 'Processing...' : (
                        <>
                            Proceed to Pay <ArrowRight size={18} />
                        </>
                    )}
                </button>

                <div className="flex justify-center gap-4 opacity-50 grayscale hover:grayscale-0 transition-opacity">
                    <Image src="https://static.cdnlogo.com/logos/p/6/paytm.svg" alt="Paytm" width={50} height={16} className="h-4 w-auto object-contain" unoptimized />
                    <Image src="https://static.cdnlogo.com/logos/p/25/phonepe.svg" alt="PhonePe" width={50} height={16} className="h-4 w-auto object-contain" unoptimized />
                    <Image src="https://static.cdnlogo.com/logos/g/80/google-pay.png" alt="Google Pay" width={50} height={16} className="h-4 w-auto object-contain" unoptimized />
                </div>
            </div>
        </form>
    );
};

export default CheckoutForm;
